    TwistSquash::SquashKeyA(POLLUX_KEY_B_E_IceLaneA, POLLUX_KEY_B_E_IceLaneB, POLLUX_KEY_B_E_IceLaneC, POLLUX_KEY_B_E_IceLaneD, &(pWorkSpace->mKeyBoxB[4U][0]));

